do $$
declare src text:='https://meslek.meb.gov.tr/upload/cop12_mem/2021_plastik_mem_cop.pdf'; b text; bra text[]:=array['Plastik İşleme','Plastik Kalıp'];
begin
foreach b in array bra loop
 insert into official_curriculum_profiles(effective_academic_year,school_type,school_subtype,program_type,field_name,branch_name,grade_level,required_course_count,required_hour_total,elective_course_min,elective_course_max,elective_hour_min,elective_hour_max,total_hour_min,total_hour_max,total_hour_target,group_rules,source_file_name,source_decision_no,source_note,active,schedule_variant,common_hours,vocational_hours,elective_vocational_hours,elective_hours,guidance_hours,enterprise_hours,applicability_status,source_page,parsed_constraints,academic_support_hours)
 select s.effective_academic_year,s.school_type,s.school_subtype,s.program_type,'Plastik Teknolojisi',b,s.grade_level,s.required_course_count,s.required_hour_total,s.elective_course_min,s.elective_course_max,s.elective_hour_min,s.elective_hour_max,s.total_hour_min,s.total_hour_max,s.total_hour_target,s.group_rules,src,'2021-33','2021-33 yaşayan MESEM Plastik Teknolojisi çizelgesi; parantezli temel ders saatleri DIPLOMA fark dersidir.',true,s.schedule_variant,s.common_hours,s.vocational_hours,s.elective_vocational_hours,s.elective_hours,s.guidance_hours,s.enterprise_hours,'CURRENTLY_VALID',case b when 'Plastik İşleme' then 5 else 6 end,s.parsed_constraints,s.academic_support_hours from official_curriculum_profiles s where s.active and s.school_type='MESEM' and s.field_name='Muhasebe ve Finansman' and s.branch_name='Muhasebe' and not exists(select 1 from official_curriculum_profiles x where x.active and x.effective_academic_year=s.effective_academic_year and x.school_type='MESEM' and coalesce(x.school_subtype,'')=coalesce(s.school_subtype,'') and coalesce(x.program_type,'')=coalesce(s.program_type,'') and x.field_name='Plastik Teknolojisi' and x.branch_name=b and x.grade_level=s.grade_level and coalesce(x.schedule_variant,'STANDARD')=coalesce(s.schedule_variant,'STANDARD'));
end loop;
insert into course_catalog(name,category,active) select n,'uygulama',true from unnest(array['Temel Plastik Teknolojisi','Plastik Teknik Resmi','Bilgisayar Destekli Çizim','Plastik Teknolojisi Temel İşlemleri','Hidrolik-Pnömatik','Ahilik Kültürü ve Girişimcilik','Plastik Enjeksiyon Teknolojisi','Plastik Ekstrüzyon Teknolojisi','Katı Modelleme','Plastik Şişirme Film (Ekstrüzyon) Teknolojisi','Plastik Şişirme Teknolojisi','Plastik Vakum Teknolojisi','Termoset Plastik Kalıplama Teknolojisi','Polimer Test Laboratuvarı','Plastik Enjeksiyon Kalıpçılığı','Plastik Ekstrüzyon Kalıpçılığı','Plastik Şişirme Kalıpçılığı','Termoset Plastik Kalıpçılığı','Plastik Vakum Kalıpçılığı','CAM (CNC) Programlama']) n where not exists(select 1 from course_catalog c where c.name=n);
insert into official_course_schedule_catalog(effective_academic_year,school_type,school_subtype,program_type,field_name,branch_name,grade_level,course_id,category,hour_options,max_selections,repeat_across_years,source_file_name,source_note,active,source_decision_no,source_page,parsed_constraints,needs_review,schedule_variant)
select p.effective_academic_year,p.school_type,p.school_subtype,p.program_type,p.field_name,p.branch_name,p.grade_level,s.course_id,s.category,s.hour_options,s.max_selections,s.repeat_across_years,src,p.source_note,true,'2021-33',p.source_page,s.parsed_constraints,false,p.schedule_variant from official_curriculum_profiles p join official_curriculum_profiles sp on sp.active and sp.school_type='MESEM' and sp.field_name='Muhasebe ve Finansman' and sp.branch_name='Muhasebe' and sp.grade_level=p.grade_level and sp.schedule_variant=p.schedule_variant join official_course_schedule_catalog s on s.active and s.school_type='MESEM' and s.field_name='Muhasebe ve Finansman' and s.branch_name='Muhasebe' and s.grade_level=sp.grade_level and s.schedule_variant=sp.schedule_variant join course_catalog c on c.id=s.course_id where p.active and p.school_type='MESEM' and p.field_name='Plastik Teknolojisi' and (s.category='zorunlu' or c.name='İşletmelerde Mesleki Eğitim') and not exists(select 1 from official_course_schedule_catalog x where x.active and x.effective_academic_year=p.effective_academic_year and x.school_type=p.school_type and coalesce(x.school_subtype,'')=coalesce(p.school_subtype,'') and coalesce(x.program_type,'')=coalesce(p.program_type,'') and coalesce(x.field_name,'')=p.field_name and coalesce(x.branch_name,'')=p.branch_name and x.grade_level=p.grade_level and x.course_id=s.course_id and coalesce(x.schedule_variant,'STANDARD')=coalesce(p.schedule_variant,'STANDARD'));
insert into official_course_schedule_catalog(effective_academic_year,school_type,program_type,field_name,branch_name,grade_level,course_id,category,hour_options,source_file_name,source_note,active,source_decision_no,source_page,parsed_constraints,needs_review,schedule_variant)
select p.effective_academic_year,'MESEM','MESEM','Plastik Teknolojisi',p.branch_name,p.grade_level,c.id,'uygulama',array[v.h],src,p.source_note,true,'2021-33',p.source_page,'[]'::jsonb,false,p.schedule_variant from official_curriculum_profiles p join lateral (select * from (values (9,'*','Temel Plastik Teknolojisi',2),(10,'*','Plastik Teknik Resmi',1),(10,'*','Bilgisayar Destekli Çizim',1),(10,'*','Plastik Teknolojisi Temel İşlemleri',2),(11,'*','Hidrolik-Pnömatik',1),(12,'*','Ahilik Kültürü ve Girişimcilik',1),(11,'Plastik İşleme','Plastik Enjeksiyon Teknolojisi',2),(11,'Plastik İşleme','Plastik Ekstrüzyon Teknolojisi',2),(11,'Plastik İşleme','Katı Modelleme',2),(12,'Plastik İşleme','Plastik Şişirme Film (Ekstrüzyon) Teknolojisi',2),(12,'Plastik İşleme','Plastik Şişirme Teknolojisi',2),(12,'Plastik İşleme','Plastik Vakum Teknolojisi',1),(12,'Plastik İşleme','Termoset Plastik Kalıplama Teknolojisi',1),(12,'Plastik İşleme','Polimer Test Laboratuvarı',1),(11,'Plastik Kalıp','Plastik Enjeksiyon Kalıpçılığı',2),(11,'Plastik Kalıp','Plastik Ekstrüzyon Kalıpçılığı',2),(11,'Plastik Kalıp','Katı Modelleme',2),(12,'Plastik Kalıp','Plastik Şişirme Kalıpçılığı',2),(12,'Plastik Kalıp','Termoset Plastik Kalıpçılığı',2),(12,'Plastik Kalıp','Plastik Vakum Kalıpçılığı',1),(12,'Plastik Kalıp','CAM (CNC) Programlama',2))t(g,br,n,h) where t.g=p.grade_level and (t.br='*' or t.br=p.branch_name)) v on true join course_catalog c on c.name=v.n where p.active and p.school_type='MESEM' and p.field_name='Plastik Teknolojisi' and not exists(select 1 from official_course_schedule_catalog x where x.active and x.effective_academic_year=p.effective_academic_year and x.school_type='MESEM' and coalesce(x.program_type,'')='MESEM' and coalesce(x.field_name,'')='Plastik Teknolojisi' and coalesce(x.branch_name,'')=p.branch_name and x.grade_level=p.grade_level and x.course_id=c.id and coalesce(x.schedule_variant,'STANDARD')=coalesce(p.schedule_variant,'STANDARD'));
end $$;